### Define OLAP Table and Materialized View in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/index.mdx

Use the OlapTable class to define a table schema and MaterializedView to create aggregated views for analytics. This is useful for setting up data warehousing and analytical queries.

```typescript
const table = new OlapTable<Event>("events");

const mv = new MaterializedView<AggregatedEvent>({
  selectStatement: sql.statement`
    SELECT count(*) as count, name
    FROM ${table}
    GROUP BY name
  `,
  selectTables: [table],
  tableName: "events",
  materializedViewName: "aggregated_events"
});
```

--------------------------------

### Define Daily Sales Summary Materialized View

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/static-report-generation.mdx

Create a materialized view to aggregate sales transactions by date, region, and product category. Ensure the sales table is configured in the pipeline before creating the view.

```typescript
import { MaterializedView, sql } from "@514labs/moose-lib";
import { salesPipeline } from "../ingest/SalesTransaction";

// Define the aggregated data model
export interface DailySalesSummary {
  saleDate: Date;
  region: string;
  productCategory: string;
  transactionCount: number;
  totalQuantity: number;
  totalRevenue: number;
}

// Get table reference from pipeline (with null check for TypeScript)
const salesTable = salesPipeline.table;
if (!salesTable) {
  throw new Error("Sales table not configured in pipeline");
}

// Create materialized view with auto-created target table
export const dailySalesMV = new MaterializedView<DailySalesSummary>({
  tableName: "DailySalesSummary",
  materializedViewName: "DailySalesSummary_MV",
  orderByFields: ["saleDate", "region", "productCategory"],
  selectTables: [salesTable],
  selectStatement: sql`
    SELECT
      toStartOfDay(saleTimestamp) AS saleDate,
      region,
      productCategory,
      count() AS transactionCount,
      sum(quantity) AS totalQuantity,
      sum(totalAmount) AS totalRevenue
    FROM ${salesTable}
    GROUP BY saleDate, region, productCategory
  `,
});

```

--------------------------------

### Create Product Performance Materialized View

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/data-warehouses.mdx

This SQL statement creates a materialized view for product performance analysis. It aggregates data by product and order date, calculating metrics like total quantity sold and revenue. Note that SummingMergeTree cannot directly store averages, so sum and count are stored for later calculation.

```sql
CREATE MATERIALIZED VIEW IF NOT EXISTS local.product_performance
ENGINE = SummingMergeTree()
ORDER BY (product_key, order_date_key)
POPULATE
AS
SELECT
    f.product_key,
    p.name as product_name,
    p.category,
    p.brand,
    f.order_date_key,
    count(*) as times_ordered,
    sum(f.quantity) as total_quantity_sold,
    sum(f.total_amount) as total_revenue,
    sum(f.unit_price) as sum_unit_price,
    count(f.unit_price) as price_count
FROM local.fact_order_items f
JOIN local.dim_product p ON f.product_key = p.product_key
GROUP BY f.product_key, p.name, p.category, p.brand, f.order_date_key;
```

--------------------------------

### Implement Materialized View Rollup

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/engines/aggregating-merge-tree.mdx

Define source and target tables with aggregation logic to pre-calculate metrics at insert time.

```typescript
import { 
  OlapTable, 
  MaterializedView,
  ClickHouseEngines,
  UInt64,
  SimpleAggregated,
  DateTime,
  sql
} from "@514labs/moose-lib";

// Source: raw events
interface PageView {
  timestamp: DateTime;
  user_id: string;
  page: string;
  duration_ms: number;
}

const pageViews = new OlapTable<PageView>("page_views", {
  orderByFields: ["timestamp", "user_id"],
});

// Target: daily aggregates
interface DailyPageStats {
  date: DateTime;
  user_id: string;
  view_count: UInt64 & SimpleAggregated<"sum", UInt64>;
  total_duration: number & SimpleAggregated<"sum", number>;
  max_duration: number & SimpleAggregated<"max", number>;
}

const targetTable = new OlapTable<DailyPageStats>("daily_page_stats", {
  engine: ClickHouseEngines.AggregatingMergeTree,
  orderByFields: ["date", "user_id"],
});

const mv = new MaterializedView<DailyPageStats>({
  materializedViewName: "mv_daily_page_stats",
  selectTables: [pageViews],
  targetTable: targetTable,
  selectStatement: sql.statement`
    SELECT
      toStartOfDay(${pageViews.columns.timestamp}) AS date,
      ${pageViews.columns.user_id}                AS user_id,
      count()                                     AS view_count,
      sum(${pageViews.columns.duration_ms})       AS total_duration,
      max(${pageViews.columns.duration_ms})       AS max_duration
    FROM ${pageViews}
    GROUP BY date, user_id
  `,
});
```

```python
from moose_lib import (
    OlapTable, 
    OlapConfig, 
    MaterializedView,
    MaterializedViewOptions,
    AggregatingMergeTreeEngine,
    simple_aggregated,
)
from pydantic import BaseModel
from datetime import datetime

# Source: raw events
class PageView(BaseModel):
    timestamp: datetime
    user_id: str
    page: str
    duration_ms: int

# Target: daily aggregates
class DailyPageStats(BaseModel):
    date: datetime
    user_id: str
    view_count: simple_aggregated('sum', int)
    total_duration: simple_aggregated('sum', int)
    max_duration: simple_aggregated('max', int)

page_views = OlapTable[PageView]("page_views", OlapConfig(
    order_by_fields=["timestamp", "user_id"]
))

daily_stats = OlapTable[DailyPageStats]("daily_page_stats", OlapConfig(
    engine=AggregatingMergeTreeEngine(),
    order_by_fields=["date", "user_id"]
))

rollup_view = MaterializedView[DailyPageStats](
    MaterializedViewOptions(
        materialized_view_name="mv_daily_page_stats",
        select_tables=[page_views],
        select_statement="""
            SELECT
                toStartOfDay(timestamp) AS date,
                user_id,
                count()                AS view_count,
                sum(duration_ms)       AS total_duration,
                max(duration_ms)       AS max_duration
            FROM {page_views}
            GROUP BY date, user_id
        """,
    ),
    target_table=daily_stats,
)
```

--------------------------------

### Define a Custom Consumption API

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/data-warehouses.mdx

Create a TypeScript API definition using the MooseStack library to query warehouse data via SQL.

```typescript
// app/apis/sales_summary.ts

import { Api } from "@514labs/moose-lib";

interface SalesSummaryParams {
  startDate: string;
  endDate: string;
}

interface SalesSummaryResult {
  date: string;
  revenue: number;
  orders: number;
  units: number;
}

export const salesSummaryApi = new Api<SalesSummaryParams, SalesSummaryResult[]>(
  "sales-summary",
  async ({ startDate, endDate }, { client, sql }) => {
    const result = await client.query.execute<SalesSummaryResult>(sql`
      SELECT
        toString(d.date) as date,
        SUM(f.total_amount) as revenue,
        COUNT(DISTINCT f.order_id) as orders,
        SUM(f.quantity) as units
      FROM fact_order_items f
      JOIN dim_date d ON f.order_date_key = d.date_key
      WHERE d.date BETWEEN ${startDate} AND ${endDate}
      GROUP BY d.date
      ORDER BY d.date
    `);

    return result.json();
  }
);
```

```typescript
export * from "./apis/sales_summary";
```

