const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const cors = require('cors');
const helmet = require('helmet');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 8000;

// Middleware
app.use(helmet());
app.use(cors());
app.use(express.json());

// Database setup
const dbPath = path.join(__dirname, 'analytics.db');
const db = new sqlite3.Database(dbPath);

// Initialize database tables
db.serialize(() => {
  // Main events table
  db.run(`CREATE TABLE IF NOT EXISTS events (
    event_id TEXT PRIMARY KEY,
    event_ts DATETIME,
    user_id TEXT,
    product_id TEXT,
    event_type TEXT,
    properties TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);

  // Hourly activity aggregation
  db.run(`CREATE TABLE IF NOT EXISTS hourly_activity (
    hour_ts TEXT PRIMARY KEY,
    event_count INTEGER,
    unique_users INTEGER,
    last_updated DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);

  // Product statistics aggregation
  db.run(`CREATE TABLE IF NOT EXISTS product_stats (
    product_id TEXT PRIMARY KEY,
    view_count INTEGER DEFAULT 0,
    cart_count INTEGER DEFAULT 0,
    purchase_count INTEGER DEFAULT 0,
    total_revenue REAL DEFAULT 0,
    last_updated DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);

  // User funnel aggregation
  db.run(`CREATE TABLE IF NOT EXISTS user_funnel (
    user_id TEXT,
    product_id TEXT,
    has_viewed INTEGER DEFAULT 0,
    has_carted INTEGER DEFAULT 0,
    has_purchased INTEGER DEFAULT 0,
    last_updated DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, product_id)
  )`);
});

// Helper function to update aggregations
function updateAggregations(event) {
  const { event_ts, user_id, product_id, event_type, properties } = event;

  // Update hourly activity
  const hour = new Date(event_ts).toISOString().substring(0, 13) + ':00:00';
  db.run(`
    INSERT INTO hourly_activity (hour_ts, event_count, unique_users)
    VALUES (?, 1, 1)
    ON CONFLICT(hour_ts) DO UPDATE SET
      event_count = event_count + 1,
      unique_users = (
        SELECT COUNT(DISTINCT user_id)
        FROM events
        WHERE strftime('%Y-%m-%d %H', event_ts) = strftime('%Y-%m-%d %H', ?)
      ),
      last_updated = CURRENT_TIMESTAMP
  `, [hour, event_ts]);

  // Update product stats
  const price = properties && properties.price ? parseFloat(properties.price) : 0;

  if (event_type === 'view') {
    db.run(`
      INSERT INTO product_stats (product_id, view_count)
      VALUES (?, 1)
      ON CONFLICT(product_id) DO UPDATE SET
        view_count = view_count + 1,
        last_updated = CURRENT_TIMESTAMP
    `, [product_id]);
  } else if (event_type === 'cart') {
    db.run(`
      INSERT INTO product_stats (product_id, cart_count)
      VALUES (?, 1)
      ON CONFLICT(product_id) DO UPDATE SET
        cart_count = cart_count + 1,
        last_updated = CURRENT_TIMESTAMP
    `, [product_id]);
  } else if (event_type === 'purchase') {
    db.run(`
      INSERT INTO product_stats (product_id, purchase_count, total_revenue)
      VALUES (?, 1, ?)
      ON CONFLICT(product_id) DO UPDATE SET
        purchase_count = purchase_count + 1,
        total_revenue = total_revenue + ?,
        last_updated = CURRENT_TIMESTAMP
    `, [product_id, price, price]);
  }

  // Update user funnel
  const viewedFlag = event_type === 'view' ? 1 : 0;
  const cartedFlag = event_type === 'cart' ? 1 : 0;
  const purchasedFlag = event_type === 'purchase' ? 1 : 0;

  db.run(`
    INSERT INTO user_funnel (user_id, product_id, has_viewed, has_carted, has_purchased)
    VALUES (?, ?, ?, ?, ?)
    ON CONFLICT(user_id, product_id) DO UPDATE SET
      has_viewed = MAX(has_viewed, ?),
      has_carted = MAX(has_carted, ?),
      has_purchased = MAX(has_purchased, ?),
      last_updated = CURRENT_TIMESTAMP
  `, [user_id, product_id, viewedFlag, cartedFlag, purchasedFlag, viewedFlag, cartedFlag, purchasedFlag]);
}

// Routes

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', timestamp: new Date().toISOString() });
});

// Ingestion endpoint
app.post('/ingest/events', (req, res) => {
  const event = req.body;

  // Validate required fields
  if (!event.event_id || !event.event_ts || !event.user_id || !event.product_id || !event.event_type) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Store event
  const stmt = db.prepare(`
    INSERT OR REPLACE INTO events (event_id, event_ts, user_id, product_id, event_type, properties)
    VALUES (?, ?, ?, ?, ?, ?)
  `);

  stmt.run(
    event.event_id,
    event.event_ts,
    event.user_id,
    event.product_id,
    event.event_type,
    JSON.stringify(event.properties || {})
  );

  stmt.finalize();

  // Update aggregations
  updateAggregations(event);

  res.json({ status: 'success', event_id: event.event_id });
});

// Top products endpoint
app.get('/analytics/top-products', (req, res) => {
  const limit = parseInt(req.query.limit) || 10;

  db.all(`
    SELECT
      product_id,
      view_count,
      cart_count,
      purchase_count,
      total_revenue,
      CAST(purchase_count AS FLOAT) / NULLIF(view_count, 0) as conversion_rate
    FROM product_stats
    ORDER BY view_count DESC, total_revenue DESC
    LIMIT ?
  `, [limit], (err, rows) => {
    if (err) {
      return res.status(500).json({ error: err.message });
    }
    res.json(rows);
  });
});

// Conversion funnel endpoint
app.get('/analytics/conversion-funnel', (req, res) => {
  db.all(`
    SELECT
      COUNT(*) as total_users,
      SUM(has_viewed) as viewed_users,
      SUM(has_carted) as carted_users,
      SUM(has_purchased) as purchased_users,
      ROUND(CAST(SUM(has_carted) AS FLOAT) / NULLIF(SUM(has_viewed), 0) * 100, 2) as view_to_cart_rate,
      ROUND(CAST(SUM(has_purchased) AS FLOAT) / NULLIF(SUM(has_carted), 0) * 100, 2) as cart_to_purchase_rate,
      ROUND(CAST(SUM(has_purchased) AS FLOAT) / NULLIF(SUM(has_viewed), 0) * 100, 2) as overall_conversion_rate
    FROM user_funnel
  `, (err, rows) => {
    if (err) {
      return res.status(500).json({ error: err.message });
    }
    res.json(rows[0] || {});
  });
});

// Hourly activity endpoint
app.get('/analytics/hourly-activity', (req, res) => {
  const hours = parseInt(req.query.hours) || 24;

  db.all(`
    SELECT
      hour_ts,
      event_count,
      unique_users
    FROM hourly_activity
    ORDER BY hour_ts DESC
    LIMIT ?
  `, [hours], (err, rows) => {
    if (err) {
      return res.status(500).json({ error: err.message });
    }
    res.json(rows);
  });
});

// Start server
app.listen(PORT, () => {
  console.log(`Analytics pipeline server running on port ${PORT}`);
  console.log(`Ingestion endpoint: POST http://localhost:${PORT}/ingest/events`);
  console.log(`Top products: GET http://localhost:${PORT}/analytics/top-products`);
  console.log(`Conversion funnel: GET http://localhost:${PORT}/analytics/conversion-funnel`);
  console.log(`Hourly activity: GET http://localhost:${PORT}/analytics/hourly-activity`);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Shutting down gracefully...');
  db.close((err) => {
    if (err) {
      console.error(err.message);
    }
    console.log('Database connection closed.');
    process.exit(0);
  });
});

