const fs = require('fs');
const path = require('path');

const INGESTION_URL = 'http://localhost:8000/ingest/events';
const EVENTS_DIR = '/data/events';

async function loadEvent(eventFile) {
  try {
    const eventData = fs.readFileSync(path.join(EVENTS_DIR, eventFile), 'utf8');
    const event = JSON.parse(eventData.trim());

    const response = await fetch(INGESTION_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(event)
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();
    console.log(`✓ Loaded ${event.event_id} - ${event.event_type} by ${event.user_id} on ${event.product_id}`);
    return result;
  } catch (error) {
    console.error(`✗ Failed to load ${eventFile}: ${error.message}`);
    throw error;
  }
}

async function loadAllEvents() {
  try {
    // Get all event files
    const eventFiles = fs.readdirSync(EVENTS_DIR)
      .filter(file => file.startsWith('evt_') && file.endsWith('.json'))
      .sort();

    console.log(`Found ${eventFiles.length} event files to load...`);

    let successCount = 0;
    let failCount = 0;

    // Load events sequentially to avoid overwhelming the server
    for (const file of eventFiles) {
      try {
        await loadEvent(file);
        successCount++;
      } catch (error) {
        failCount++;
      }

      // Small delay between requests
      await new Promise(resolve => setTimeout(resolve, 10));
    }

    console.log(`\nLoad complete: ${successCount} successful, ${failCount} failed`);

    // Verify final analytics
    console.log('\nFinal analytics:');

    const topProducts = await fetch('http://localhost:8000/analytics/top-products').then(r => r.json());
    console.log('Top Products:', topProducts);

    const funnel = await fetch('http://localhost:8000/analytics/conversion-funnel').then(r => r.json());
    console.log('Conversion Funnel:', funnel);

    const hourly = await fetch('http://localhost:8000/analytics/hourly-activity?hours=10').then(r => r.json());
    console.log('Hourly Activity:', hourly);

  } catch (error) {
    console.error('Fatal error:', error.message);
    process.exit(1);
  }
}

loadAllEvents();

