async function measureEndpoint(url, name) {
  const measurements = [];
  const iterations = 10;

  console.log(`\nTesting ${name}:`);

  for (let i = 0; i < iterations; i++) {
    const start = Date.now();
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }
      await response.json();
      const duration = Date.now() - start;
      measurements.push(duration);
      console.log(`  Iteration ${i + 1}: ${duration}ms`);
    } catch (error) {
      console.error(`  Iteration ${i + 1}: ERROR - ${error.message}`);
      measurements.push(1000); // Penalty for errors
    }

    // Small delay between requests
    await new Promise(resolve => setTimeout(resolve, 50));
  }

  const avg = measurements.reduce((a, b) => a + b, 0) / measurements.length;
  const max = Math.max(...measurements);
  const min = Math.min(...measurements);

  console.log(`  Average: ${avg.toFixed(1)}ms`);
  console.log(`  Min: ${min}ms`);
  console.log(`  Max: ${max}ms`);

  return { name, avg, max, min, measurements, passed: max < 200 };
}

async function testAllEndpoints() {
  console.log('🚀 Performance Test - All endpoints must respond under 200ms\n');

  const endpoints = [
    { url: 'http://localhost:8000/analytics/top-products', name: 'Top Products' },
    { url: 'http://localhost:8000/analytics/conversion-funnel', name: 'Conversion Funnel' },
    { url: 'http://localhost:8000/analytics/hourly-activity', name: 'Hourly Activity' },
    { url: 'http://localhost:8000/health', name: 'Health Check' }
  ];

  const results = [];

  for (const endpoint of endpoints) {
    const result = await measureEndpoint(endpoint.url, endpoint.name);
    results.push(result);
  }

  // Summary
  console.log('\n📊 PERFORMANCE TEST SUMMARY');
  console.log('=' .repeat(50));

  let allPassed = true;
  for (const result of results) {
    const status = result.passed ? '✅ PASS' : '❌ FAIL';
    console.log(`${status} ${result.name}: avg=${result.avg.toFixed(1)}ms, max=${result.max}ms`);
    if (!result.passed) allPassed = false;
  }

  console.log('=' .repeat(50));
  console.log(allPassed ? '🎉 ALL ENDPOINTS PASSED' : '⚠️ SOME ENDPOINTS FAILED');

  // Test ingestion performance
  console.log('\n🔄 Testing Ingestion Performance:');
  const ingestionStart = Date.now();

  const testEvent = {
    event_id: `perf_test_${Date.now()}`,
    event_ts: new Date().toISOString(),
    user_id: 'perf_user',
    product_id: 'perf_prod',
    event_type: 'view',
    properties: {}
  };

  try {
    const response = await fetch('http://localhost:8000/ingest/events', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(testEvent)
    });

    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    await response.json();

    const ingestionTime = Date.now() - ingestionStart;
    const ingestionPassed = ingestionTime < 200;

    console.log(`  Ingestion time: ${ingestionTime}ms ${ingestionPassed ? '✅' : '❌'}`);

    return allPassed && ingestionPassed;

  } catch (error) {
    console.error(`  Ingestion ERROR: ${error.message} ❌`);
    return false;
  }
}

testAllEndpoints().then(allPassed => {
  process.exit(allPassed ? 0 : 1);
});

